INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_111'), 1, 'A `pull_request` run does not test the head of the branch: look at which ref `actions/checkout` fetches for it, and at what a fork can and cannot trigger in the base repository.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_111'), 2, 'Every job gets a fresh virtual machine. What does `needs:` change about when job B starts, and what does it not change about the files on job B''s disk?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_111'), 3, 'Read the GitHub docs on path filters and required status checks together: what state does a check stay in when its workflow never started?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_111');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_111'), 'Every commit pushed to an open pull request starts the workflow twice:

```yaml
# .github/workflows/ci.yml
on: [push, pull_request]
```

```text
ci  #212  feature/momo-pay  push           ✓ 3m 41s
ci  #213  feature/momo-pay  pull_request   ✓ 3m 39s
```

Statement: "Removing `pull_request` and keeping `push` is the right fix: the push run already tests the same commit."', 'single_choice'::question_type, 'False. The `pull_request` run checks out `refs/pull/<n>/merge`, the branch merged into the current `main`: the code that will land. The push run tests only the branch head, which can pass while the merge result fails. Pull requests from forks never trigger `push` in the base repository at all. The usual fix keeps `pull_request` and limits `push` to `branches: [main]`, so a feature branch push starts nothing and a merge to main runs once.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_111'), 'The workflow installs once and tests in a second job:

```yaml
jobs:
  install:
    runs-on: ubuntu-24.04
    steps:
      - uses: actions/checkout@v5
      - run: npm ci
        working-directory: api
  test:
    needs: install
    runs-on: ubuntu-24.04
    steps:
      - run: npm test
        working-directory: api
```

```text
test  Run npm test
  npm error code ENOENT
  npm error path /home/runner/work/app/app/api/package.json
```

Statement: "`needs` only orders the jobs. Each job runs on a fresh runner, so `test` has to check out the code and install the dependencies itself (or download an artifact that `install` uploaded)."', 'single_choice'::question_type, 'True. Jobs run on separate virtual machines; `needs: install` makes `test` wait for `install` to succeed and gives it access to `needs.install.outputs`, but no files. Steps share a workspace only within one job. Here `test` has not even checked out the repository, so `api/package.json` does not exist. The usual layout gives each job its own checkout + setup + `npm ci` (made fast by the cache in the next lesson).', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_111') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_111'), 'The team added a path filter, and branch protection requires the `test` check. A pull request that only edits `docs/deploy.md` now shows:

```yaml
on:
  pull_request:
    branches: [main]
    paths-ignore: ["docs/**"]
```

```text
Some checks haven''t completed yet
  ci / test   Expected — Waiting for status to be reported
Merging is blocked
```

Statement: "The workflow was skipped by the path filter, and a required check of a workflow that never ran stays pending, so this pull request cannot be merged as it is."', 'single_choice'::question_type, 'True. GitHub documents this: when a workflow is skipped because of path filtering (or branch filtering, or a skip instruction in the commit message), its checks stay "Pending", and a pull request that requires them is blocked. Teams handle it by not requiring that check, by running a tiny always-on job that reports the status, or by filtering inside the job instead of in `on:`. The misconception is that a skipped workflow counts as passed.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_111') AND order_index = 3)
    RETURNING id
)
