-- challenge chal_coding_gha_112 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_gha_112', (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gha-1-1' AND is_deleted = false LIMIT 1), 'pull-request-workflow', 'Write the pull request workflow', 'Rice Rocket''s CI file came from a blog post: it ran on every push to every branch, twice per pull request, on docs-only changes, with a write-all token and no time limit. The editor holds the corrected `.github/workflows/ci.yml` with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that: the workflow runs for pull requests into `main` and for pushes to `main`, never for docs-only changes (`docs/**`, any `*.md`), feature branch pushes or tag pushes; the token can only read the repository; `lint` checks out the code, installs Node from `api/.nvmrc` and the locked dependencies with `npm ci`, and gives up after 10 minutes; `test` starts only after `lint` passed. Run grades the file with a simulator of GitHub''s trigger filters and job graph.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
