INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_112'), 1, 'Each test names events: a pull request into main, a push to a feature branch, a tag push, a docs-only change. For each one, which key under `on:` decides whether the workflow starts?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_112'), 2, 'Look at `branches:` and `paths-ignore:` under each event, the workflow-level `permissions:` map, `timeout-minutes:` on a job, and `needs:`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_112'), 3, 'A workflow for a `web/` folder that runs on pull requests into `develop` unless only images changed: `on: { pull_request: { branches: [develop], paths-ignore: ["web/img/**"] } }`, with `permissions: { contents: read }` and a job that starts with `actions/checkout`, then `actions/setup-node` with `node-version-file`, then `npm ci`.');
