VALUES ('chal_coding_gha_122', (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gha-1-2' AND is_deleted = false LIMIT 1), 'npm-dependency-cache', 'Cache npm downloads without stale installs', 'Rice Rocket''s test job spends 2.5 of its 4 minutes in `npm ci` downloading packages. The first cache a teammate added kept `api/node_modules` under a fixed key and skipped `npm ci` on a hit: the day `zod` joined the lockfile, CI restored the old `node_modules` and failed with `Cannot find module ''zod''`. The editor holds the test job with the `actions/cache` step and the install step missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that: npm''s download cache (`~/.npm`) is kept between runs; a run with an unchanged `api/package-lock.json` restores it exactly and downloads nothing; a run after the lockfile changed restores the newest cache of the same OS and downloads only the changed packages; every run installs from the lockfile, so `node_modules` always matches it; a Windows runner never gets a Linux cache. Run grades the file with a simulator of actions/cache (immutable keys, restore-keys, branch scopes) over a series of CI runs.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
