VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_122'), 'First run misses and downloads everything; the next run with the same lockfile hits exactly', '{"checks":["parse","runs"],"runs":[{"id":"first","branch":"main","os":"Linux","lock":"3f9c1e"},{"id":"second","branch":"main","os":"Linux","lock":"3f9c1e"}]}', '{"parse":"ok","runs":{"first":{"restore":"miss","download":"all","node_modules":"fresh"},"second":{"restore":"exact","download":"none","node_modules":"fresh"}}}', 6, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_122'), 'After a lockfile change: partial restore, only new packages, fresh node_modules', '{"checks":["runs"],"runs":[{"id":"before","branch":"main","os":"Linux","lock":"3f9c1e"},{"id":"zod-added","branch":"main","os":"Linux","lock":"8b27d4"},{"id":"after","branch":"main","os":"Linux","lock":"8b27d4"}]}', '{"runs":{"before":{"restore":"miss","download":"all","node_modules":"fresh"},"zod-added":{"restore":"partial","download":"changed packages","node_modules":"fresh"},"after":{"restore":"exact","download":"none","node_modules":"fresh"}}}', 6, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_122'), 'A feature branch restores the cache saved on main', '{"checks":["runs"],"runs":[{"id":"main","branch":"main","os":"Linux","lock":"3f9c1e"},{"id":"feature","branch":"feature/momo-pay","os":"Linux","lock":"3f9c1e"}]}', '{"runs":{"main":{"restore":"miss","download":"all","node_modules":"fresh"},"feature":{"restore":"exact","download":"none","node_modules":"fresh"}}}', 6, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_122'), 'A branch sees its own caches and main''s, never a sibling branch''s', '{"checks":["runs"],"runs":[{"id":"main","branch":"main","os":"Linux","lock":"3f9c1e"},{"id":"momo","branch":"feature/momo-pay","os":"Linux","lock":"8b27d4"},{"id":"zalo","branch":"feature/zalo-login","os":"Linux","lock":"8b27d4"},{"id":"momo-again","branch":"feature/momo-pay","os":"Linux","lock":"8b27d4"}]}', '{"runs":{"main":{"restore":"miss","download":"all","node_modules":"fresh"},"momo":{"restore":"partial","download":"changed packages","node_modules":"fresh"},"zalo":{"restore":"partial","download":"changed packages","node_modules":"fresh"},"momo-again":{"restore":"exact","download":"none","node_modules":"fresh"}}}', 4, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_122'), 'A Windows runner does not restore the Linux cache', '{"checks":["runs"],"runs":[{"id":"linux","branch":"main","os":"Linux","lock":"3f9c1e"},{"id":"windows","branch":"main","os":"Windows","lock":"3f9c1e"}]}', '{"runs":{"linux":{"restore":"miss","download":"all","node_modules":"fresh"},"windows":{"restore":"miss","download":"all","node_modules":"fresh"}}}', 4, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_122'), 'One cache entry is saved per lockfile, never overwritten', '{"checks":["saved"],"runs":[{"id":"before","branch":"main","os":"Linux","lock":"3f9c1e"},{"id":"zod-added","branch":"main","os":"Linux","lock":"8b27d4"},{"id":"after","branch":"main","os":"Linux","lock":"8b27d4"}]}', '{"saved":["main npm-Linux-3f9c1e","main npm-Linux-8b27d4"]}', 4, false, true, 6);
