INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_131'), 1, 'Expand the matrix by hand: write every node/os pair, then apply the `include` entry with GitHub''s rule about not overwriting an original matrix value.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_131'), 2, 'Read the last line of the run log: which setting decided that one failure stops the other combinations, and what is its default?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_131'), 3, 'Where does the test process run: on the runner''s virtual machine, or inside a container on the job''s Docker network? Which of the two can resolve the name `postgres`?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_131'), 'The team wants coverage from one combination only:

```yaml
strategy:
  matrix:
    node: [22, 24]
    os: [ubuntu-24.04, windows-2025]
    include:
      - node: 24
        os: ubuntu-24.04
        coverage: true
```

Statement: "This matrix starts 5 jobs: the four node/os combinations, plus one extra job on Node 24 and Ubuntu that collects coverage."', 'single_choice'::question_type, 'False. It starts 4 jobs. An `include` entry is added to every original combination it can join without overwriting an original matrix value; `{node: 24, os: ubuntu-24.04}` already exists, so that job just gains `coverage: true` (read as `matrix.coverage`, empty in the other three). An include entry creates a new combination only when it would overwrite an original value, as `node: 25` would. The misconception is that every `include` entry adds a job.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_131'), 'The first matrix run after a pull request that changed a query:

```text
integration (22, 16)   failed after 1m 12s
integration (22, 17)   cancelled
integration (24, 16)   cancelled
integration (24, 17)   cancelled

The strategy configuration was canceled because "integration._22_16" failed
```

Statement: "With `fail-fast: false` in the strategy, the three other combinations would run to the end, and their results would show whether the failure is specific to Postgres 16, to Node 22, or to neither."', 'single_choice'::question_type, 'True. `fail-fast` defaults to `true`: the first failing job of a matrix cancels every job of that matrix that is still queued or running. Here that hid the only useful information. With `fail-fast: false` every combination reports its own result; if (22, 17) and (24, 17) pass while (24, 16) fails too, the query depends on a Postgres 17 feature. The cost is paying for the runs that continue after a failure.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
