WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_131'), 'The job runs on the runner, with Postgres as a service container; the URL was copied from `compose.yaml`:

```yaml
jobs:
  integration:
    runs-on: ubuntu-24.04
    services:
      postgres:
        image: postgres:17
        ports:
          - 5432:5432
    steps:
      - run: npm run test:integration
        env:
          DATABASE_URL: postgres://postgres:test@postgres:5432/postgres
```

```text
Error: getaddrinfo ENOTFOUND postgres
```

Statement: "The service name resolves only when the job itself runs in a container (`container:`); a job running directly on the runner reaches the service through the mapped port on `localhost`."', 'single_choice'::question_type, 'True. Service containers join a Docker network that the job''s own container is attached to when the job uses `container:`; there, `postgres` resolves through Docker''s DNS. A job without `container:` runs on the runner VM, outside that network, and reaches the service only through the port published on the host: `localhost:5432` with `ports: - 5432:5432`. The misconception is that Actions services work like Compose services for every job.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_131') AND order_index = 3)
    RETURNING id
)
