-- challenge chal_coding_gha_142 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_gha_142', (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gha-2-1' AND is_deleted = false LIMIT 1), 'build-push-traceable-image', 'Build the image on every pull request, push it with traceable tags', 'Until now the api image was built on a laptop and pushed as `latest`, so nobody could tell which commit ran on the VPS, and a rollback meant rebuilding an old commit. The first workflow that replaced it also pushed from pull requests and failed for pull requests from forks. The editor holds `.github/workflows/image.yml` with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that: the workflow runs for pull requests into `main`, pushes to `main` and tags like `v1.4.0`, and nothing else; the token can read the repository and write packages, and the login to `ghcr.io` uses that token (no personal token, no other secret is set in this repository); a pull request builds the image but signs in to nothing and pushes nothing; every image carries a `sha-<7 chars>` tag, plus the branch name on a push to main, `pr-<number>` on a pull request, and `1.4.0`, `1.4` and `latest` on the release tag `v1.4.0`; the build uses `api/` as its context and the GitHub Actions cache (`type=gha`, `mode=max` on export). Run grades the file with a simulator of the trigger filters, the token and the three Docker actions.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
