INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_142'), 1, 'Follow one event at a time through the steps: on a pull request, which steps run, what does `push:` evaluate to, and what would a push without a login answer? On the tag push, which `tags:` lines of the metadata step produce something?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_142'), 2, 'Look at `tags:` next to `branches:` under `push`, the `packages` scope in `permissions:`, the `if:` of the login step, the `type=` lines of `docker/metadata-action` (it adds `latest` by itself on a release), and an expression for `push:` instead of a constant.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_142'), 3, 'An image for the `web/` folder that builds on pull requests into `develop` and pushes only from `develop`: `if: github.event_name != ''pull_request''` on the login, metadata `tags: |` with `type=sha` and `type=ref,event=branch`, and `push: ${{ github.event_name != ''pull_request'' }}` with `tags: ${{ steps.meta.outputs.tags }}` on the build.');
