-- challenge chal_quiz_gha_151 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_gha_151', (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gha-2-2' AND is_deleted = false LIMIT 1), 'environments-concurrency-quiz', 'Read the deploy queue', 'Three statements about what Rice Rocket saw while adding concurrency groups and environments to its workflows. Decide whether each one is true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_151');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_151'), 1, 'Count the slots of one concurrency group: how many runs can be in progress, and how many can wait? What happens to a waiting run when a newer one arrives?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_151'), 2, 'A concurrency group is a string. Which runs share it when it is the constant `ci`, and which share it when it contains `github.ref`?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_151'), 3, 'Look at where `PROD_SSH_KEY` was created (Settings > Environments > production) and at which job declares `environment: production`.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_151');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_151'), 'The deploy job got a concurrency group, then three pull requests were merged within two minutes:

```yaml
jobs:
  deploy:
    concurrency:
      group: deploy
      cancel-in-progress: false
```

```text
deploy  #88  main  a1f3c2e  In progress
deploy  #89  main  b7d9e01  Cancelled
  Canceling since a higher priority waiting request for deploy exists
deploy  #90  main  c4e2a9b  Pending
```

Statement: "With `cancel-in-progress: false`, GitHub queues every run of the group, so #89 was cancelled by a bug and should have deployed after #88."', 'single_choice'::question_type, 'False. A concurrency group holds at most one running and one pending job. When #90 arrived while #89 was pending, #89 was cancelled and #90 took the pending slot; that is the documented behaviour, not a bug. For deploys of `main` it is what you want: #90 contains every commit of #89, so deploying c4e2a9b right after a1f3c2e skips nothing. `cancel-in-progress: false` only protects the running deploy (#88) from being cut short. The misconception is that a group is a FIFO queue of unlimited length.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_151') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_151'), 'The CI workflow cancels outdated runs, but two developers keep losing their checks:

```yaml
# .github/workflows/ci.yml
concurrency:
  group: ci
  cancel-in-progress: true
```

```text
ci  #301  PR #41 feature/momo-pay   Cancelled  (higher priority request for ci)
ci  #302  PR #42 feature/zalo-login In progress
```

Statement: "Setting `cancel-in-progress: false` is the fix: then each pull request gets its own CI run."', 'single_choice'::question_type, 'False. The group name `ci` is the same for every run of the workflow, so all pull requests share one slot. With `cancel-in-progress: false` they would queue behind each other, and a waiting run would still be cancelled by the next one. The fix is a group per ref: `group: ci-${{ github.ref }}` (each pull request has its own `refs/pull/<n>/merge`), keeping `cancel-in-progress: true` so a new push to the same pull request cancels only that pull request''s outdated run.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_151') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_151'), '`PROD_SSH_KEY` was created as a secret of the environment `production`. A smoke-test job added after the deploy fails:

```yaml
  smoke:
    needs: deploy-production
    runs-on: ubuntu-24.04
    steps:
      - run: ./deploy/smoke.sh
        env:
          SSH_KEY: ${{ secrets.PROD_SSH_KEY }}
```

```text
Run ./deploy/smoke.sh
  SSH_KEY: 
deploy@203.0.113.10: Permission denied (publickey).
```

Statement: "Environment secrets reach only jobs that reference that environment; `smoke` has no `environment: production`, so `secrets.PROD_SSH_KEY` is an empty string there."', 'single_choice'::question_type, 'True. Secrets stored on an environment are available only to a job that declares `environment:` with that name, and only after its protection rules pass (reviewer, allowed branch). Any other job gets an empty string, without an error, which is why the log shows `SSH_KEY:` with no value. Either add `environment: production` to `smoke` (it then also waits for its rules) or run the smoke test as steps of `deploy-production`. The misconception is that a secret defined anywhere in the repository settings reaches every job.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_151') AND order_index = 3)
    RETURNING id
)
