SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_gha_152 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_gha_152', (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gha-2-2' AND is_deleted = false LIMIT 1), 'staging-production-deploys', 'Deploy main to staging, then production, one deploy at a time', 'Rice Rocket''s deploy workflow shipped every push to main straight to the VPS. Two merges a minute apart deployed at the same time and the older, slower one finished last, so the old version went live; anyone who merged deployed to production without approval; and a first fix with `cancel-in-progress: true` killed a deploy halfway through its migration. The editor holds `.github/workflows/deploy.yml` with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. The environments already exist in the repository settings: `staging` (secret `STAGING_SSH_KEY`) and `production` (a required reviewer, deployments from main only, secret `PROD_SSH_KEY`). Fill every line so that: `deploy-staging` uses the environment `staging` with the URL `https://staging.ricerocket.vn` and `deploy-production` the environment `production` with `https://ricerocket.vn`; each environment runs one deploy at a time and never cancels a running deploy, so the newest commit ends up live; production starts only after staging succeeded; a manual run from any branch other than main deploys nothing. Run grades the file with a simulator of jobs, environments and concurrency groups on one clock.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
