INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_152'), 1, 'Draw the three merges on a timeline: when does each staging deploy start and end with no group, with a shared group, and with `cancel-in-progress: true`? Which commit is live at the end of each?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_152'), 2, 'Look at `environment:` with `name` and `url`, a job-level `concurrency:` with a constant `group` and `cancel-in-progress`, `needs:` between the two deploy jobs, and an `if:` on `github.ref`.'),
