INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_161'), 1, 'With `pull_request_target`, separate two things: where the workflow file comes from, and whose code the steps actually execute after the checkout.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_161'), 2, 'The `sub` claim of GitHub''s OIDC token names the repository plus the environment, the ref, or `pull_request`. Which of those forms does the pattern `repo:rice-rocket/app:*` match?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_161'), 3, 'When `permissions:` is a map, what happens to every scope the map does not name? Then look at what `actions/checkout` needs to read a private repository.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_161');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_161'), 'A workflow posts test coverage to a service on every pull request, forks included:

```yaml
on: pull_request_target
jobs:
  coverage:
    runs-on: ubuntu-24.04
    steps:
      - uses: actions/checkout@v5
        with:
          ref: ${{ github.event.pull_request.head.sha }}
      - run: npm ci && npm test -- --coverage
        working-directory: api
        env:
          COVERAGE_TOKEN: ${{ secrets.COVERAGE_TOKEN }}
```

Statement: "This is safe: with `pull_request_target` the workflow file always comes from the base branch, so a fork cannot change what runs."', 'single_choice'::question_type, 'False. The workflow file is the base branch''s, but its second step runs the fork''s code: `npm ci` runs the install scripts of the fork''s `package.json`, and `npm test` runs the fork''s test files, all with `COVERAGE_TOKEN` in the environment and a token that can write to the base repository. This is the "pwn request" pattern. Run untrusted code under `pull_request` (no secrets for forks), and if a privileged step must follow, run it in a separate `workflow_run` workflow that never executes the pull request''s code. The misconception is that controlling the YAML means controlling everything it executes.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_161') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_161'), 'The IAM role that deploys the web site trusts GitHub''s OIDC provider with these conditions:

```json
"Condition": {
  "StringEquals": { "token.actions.githubusercontent.com:aud": "sts.amazonaws.com" },
  "StringLike": { "token.actions.githubusercontent.com:sub": "repo:rice-rocket/app:*" }
}
```

```text
sub claims seen in CloudTrail last week
repo:rice-rocket/app:environment:production
repo:rice-rocket/app:ref:refs/heads/feature/momo-pay
repo:rice-rocket/app:pull_request
```

Statement: "Any workflow run in `rice-rocket/app` that asks for `id-token: write` can assume this role, including one on a feature branch or a `pull_request` run from a branch of the same repository; `repo:rice-rocket/app:environment:production` would limit it to jobs that use the production environment."', 'single_choice'::question_type, 'True. `*` matches every subject the repository can produce: environment, branch or tag ref, and `pull_request`. Anyone who can push a branch can write a workflow that requests an ID token and assumes the production role. When a job references an environment, the `sub` becomes `repo:<owner>/<repo>:environment:<name>`, so matching that exact value ties the role to the environment, whose protection rules (required reviewers, deployment branches) then guard the credentials. The misconception is that the repository name alone is a strong enough boundary.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_161') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_161'), 'A new deploy workflow sets only the OIDC permission at the top. The repository is private:

```yaml
permissions:
  id-token: write
jobs:
  deploy:
    runs-on: ubuntu-24.04
    steps:
      - uses: actions/checkout@v5
```

```text
Run actions/checkout@v5
  remote: Repository not found.
  Error: fatal: repository ''https://github.com/rice-rocket/app/'' not found
```

Statement: "A permissions map grants only the scopes it names, so this token has no `contents: read` and cannot clone the private repository; adding `contents: read` next to `id-token: write` fixes it."', 'single_choice'::question_type, 'True. Once `permissions:` is set, every scope it does not list is `none`; the repository default (read for contents and packages) no longer applies. For a private repository the clone then fails with "Repository not found", because GitHub hides private repositories from tokens that cannot read them. Listing `contents: read` and `id-token: write` gives exactly what the job needs. The misconception is that the map adds to the defaults.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_161') AND order_index = 3)
    RETURNING id
)
