-- challenge chal_coding_gha_162 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_gha_162', (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gha-2-3' AND is_deleted = false LIMIT 1), 'fix-web-deploy-workflow', 'Fix the web deploy workflow', 'The security review of `.github/workflows/deploy-web.yml` found four problems: long-lived AWS access keys stored as repository secrets, a `write-all` token, a third-party action referenced by a moving tag, and a step that pastes the head commit message into a shell script (a commit titled `Fix"; curl ... | sh; echo "` would run that command on the runner). The editor holds the fixed workflow with its key blocks missing, each marked by a `# [ ]` line; some pieces are the original, vulnerable versions. Fill every line so that: the token can only read the repository unless a job asks for more; the `deploy` job can read the code and request an OIDC token, and nothing else; AWS credentials come from assuming the role `rice-rocket-web-deploy` in `ap-southeast-1` through OIDC, with no stored keys; every action not owned by GitHub is pinned to a full commit SHA; the commit message reaches the shell only as an environment variable. Run grades the file with a simulator of GitHub''s token permissions, the AWS credentials action and expression rendering.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
