-- challenge chal_quiz_gha_171 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_gha_171', (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gha-3-1' AND is_deleted = false LIMIT 1), 'deploy-health-gate-quiz', 'Read the deploy that went green', 'Three statements about the deploy job that reported success while Rice Rocket''s api was down. Decide whether each one is true.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_171');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_171'), 1, 'The runner decides pass or fail from one thing only: the exit code of the step''s shell. What exit code does curl return when the server answers 502 and no `-f` flag is set?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_171'), 2, 'Every step has an implicit `if: success()` unless it says otherwise. What does that do to a step placed after one that failed?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_171'), 3, 'Step outputs live inside their job. Look at which map a later job reads through `needs.<job>.outputs`, and where that map is declared.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_171');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_171'), 'The deploy job checked the api after `docker compose up -d`:

```yaml
      - name: Check health
        run: curl -s -o /dev/null -w ''%{http_code}\n'' https://api.ricerocket.vn/health
```

```text
Check health
  502
  ✓ Check health (1s)
Job deploy succeeded
```

Statement: "The step passed because the runner retried the request and the 502 was transient; the api was healthy by the time the step finished."', 'single_choice'::question_type, 'False. The runner does not retry steps, and a step passes whenever its shell exits 0. curl exits 0 on any HTTP answer, 502 included, unless it is told to treat HTTP errors as failures: `curl -fsS` (or `--fail-with-body`) exits 22 on a 4xx or 5xx, which fails the step. The log printed 502 and the step still went green; nothing in it shows a second request. The misconception is that a step fails when its output looks bad: only the exit code counts.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_171') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_171'), 'After the health step failed, the rollback step did not run:

```yaml
      - name: Health gate
        run: node deploy/gate.js
      - name: Roll back
        run: ssh deploy@vps ''cd /srv/rice-rocket && TAG=1.3.2 docker compose up -d''
```

```text
X Health gate
  Error: Process completed with exit code 1.
- Roll back   (skipped)
```

Statement: "A runner error skipped the rollback step; re-running the failed job will run it."', 'single_choice'::question_type, 'False. Every step without an `if:` runs as `if: success()`, so once Health gate fails every later plain step is skipped: that is the documented behavior, not a runner error, and a re-run skips it again. A cleanup step that must run after a failure needs `if: failure()` (or `always()` for both cases). Better still, keep the rollback inside the gate script, where it runs right after the failed check and the step still exits non-zero.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_171') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_171'), 'The deploy job writes the version it shipped, and a later job posts it to the team chat:

```yaml
jobs:
  deploy:
    runs-on: ubuntu-24.04
    steps:
      - id: gate
        run: echo "version=1.4.0" >> "$GITHUB_OUTPUT"
  announce:
    needs: deploy
    runs-on: ubuntu-24.04
    steps:
      - run: echo "Shipped ${{ needs.deploy.outputs.version }}"
```

```text
announce  Run echo "Shipped "
  Shipped
```

Statement: "`needs.deploy.outputs` holds only what the deploy job declares in its own `outputs:` map, so the job needs `outputs: { version: ${{ steps.gate.outputs.version }} }`."', 'single_choice'::question_type, 'True. A step output (`$GITHUB_OUTPUT`) is visible to later steps of the same job as `steps.gate.outputs.version`. Other jobs see only the job-level `outputs:` map, which maps names to step outputs; without it `needs.deploy.outputs.version` is an empty string, and the expression does not fail, so the bug shows up only as a blank message.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_gha_171') AND order_index = 3)
    RETURNING id
)
