SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_gha_172 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_gha_172', (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gha-3-1' AND is_deleted = false LIMIT 1), 'deploy-health-gate', 'Gate the deploy on health, roll back on failure', 'Rice Rocket''s deploy job ran `docker compose up -d` over SSH and went green at once, while image 1.4.0 crash-looped for ten minutes. The new step runs `deploy/gate.js` on the VPS. The editor holds the module with its key blocks missing, each marked by a `// [ ]` line; some pieces are wrong on purpose. `gateDeploy({ release, previous, policy }, io)` must: roll `release` out; ask `io.health()` once per `policy.intervalMs` until `policy.okInARow` answers in a row have status 200 and report `version === release`, or until `policy.timeoutMs` has passed (a thrown error is a failed check and breaks the streak; do not sleep after the last good answer); when healthy, write the outputs `deployed=<release>` and `rolled_back=false`, add a summary line and return `{ status: "deployed", version: release, checks, exitCode: 0 }`; otherwise roll `previous` back out, write `deployed=<previous>` and `rolled_back=true`, add a summary line and return `{ status: "rolled_back", version: previous, checks, exitCode: 1 }`. On a first deploy (`previous` is null) there is nothing to restore: write `rolled_back=false` and a summary line, and return `{ status: "failed", version: release, checks, exitCode: 1 }`. Run grades it against a scripted server and a fake clock.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
