INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_172'), 1, 'Walk through one failing deploy on paper: which answers come back from the server while the old container stops and the new one crash-loops, and which of them may count toward the streak?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_172'), 2, 'Look at the loop: one piece asks for health and turns a thrown error into a failed check, the next one updates `streak`. After the loop, the order is: healthy, then no previous version, then roll back.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_172'), 3, 'A queue consumer that waits for 5 good batches in a row from worker version 2.0: `if (batch && batch.ok && batch.workerVersion === "2.0") good++; else good = 0;`, and when time runs out it calls `scale("1.9")`, logs the reason and returns `{ exitCode: 1 }` so the job fails.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_172'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"rollout-release","label":"Roll the new tag out on the server","code":"await io.rollout(release);"},{"id":"ask-health","label":"Ask /health once; no answer counts as down","code":"checks++;\nlet answer = null;\ntry {\n    answer = await io.health();\n} catch {\n    answer = null;\n}"},{"id":"count-healthy-streak","label":"Count healthy answers in a row from the new version","code":"if (answer && answer.status === 200 && answer.version === release) streak++;\nelse streak = 0;"},{"id":"report-deployed","label":"Healthy: record the new version and pass the step","code":"if (streak >= policy.okInARow) {\n    io.output(\"deployed\", release);\n    io.output(\"rolled_back\", \"false\");\n    io.summary(`${release} is live: ${streak} healthy checks in a row`);\n    return { status: \"deployed\", version: release, checks, exitCode: 0 };\n}"},{"id":"no-previous","label":"First deploy: nothing to roll back to","code":"if (previous === null) {\n    io.output(\"rolled_back\", \"false\");\n    io.summary(`${release} failed its health gate and there is no previous version to restore`);\n    return { status: \"failed\", version: release, checks, exitCode: 1 };\n}"},{"id":"roll-back","label":"Unhealthy: restore the previous tag and fail the step","code":"await io.rollout(previous);\nio.output(\"deployed\", previous);\nio.output(\"rolled_back\", \"true\");\nio.summary(`${release} failed its health gate after ${checks} checks; rolled back to ${previous}`);\nreturn { status: \"rolled_back\", version: previous, checks, exitCode: 1 };"},{"id":"roll-back-exit-zero","label":"Unhealthy: restore the previous tag and fail the step","code":"await io.rollout(previous);\nio.output(\"deployed\", previous);\nio.output(\"rolled_back\", \"true\");\nio.summary(`${release} failed its health gate after ${checks} checks; rolled back to ${previous}`);\nreturn { status: \"rolled_back\", version: previous, checks, exitCode: 0 };","distractor":true},{"id":"streak-any-version","label":"Count healthy answers in a row from the new version","code":"if (answer && answer.status === 200) streak++;\nelse streak = 0;","distractor":true},{"id":"streak-no-reset","label":"Count healthy answers in a row from the new version","code":"if (answer && answer.status === 200 && answer.version === release) streak++;","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_172');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_172'), 'Ships 1.4.0 after three good answers in a row from the new version', '{"release":"1.4.0","previous":"1.3.2","policy":{"intervalMs":5000,"timeoutMs":60000,"okInARow":3},"health":["refused",{"status":200,"version":"1.3.2"},{"status":200,"version":"1.4.0"}]}', '{"result":{"status":"deployed","version":"1.4.0","checks":5,"exitCode":0},"rollouts":["1.4.0"],"outputs":{"deployed":"1.4.0","rolled_back":"false"},"checksAt":[0,5000,10000,15000,20000],"elapsedMs":20000,"summary":true}', 5, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_172'), 'Crash loop: rolls back to 1.3.2 at the deadline and fails the step', '{"release":"1.4.0","previous":"1.3.2","policy":{"intervalMs":5000,"timeoutMs":30000,"okInARow":3},"health":[{"status":502,"version":null},"refused"]}', '{"result":{"status":"rolled_back","version":"1.3.2","checks":6,"exitCode":1},"rollouts":["1.4.0","1.3.2"],"outputs":{"deployed":"1.3.2","rolled_back":"true"},"checksAt":[0,5000,10000,15000,20000,25000],"elapsedMs":30000,"summary":true}', 5, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_172'), 'The old container answering 200 does not count as the new version', '{"release":"1.4.0","previous":"1.3.2","policy":{"intervalMs":5000,"timeoutMs":20000,"okInARow":2},"health":[{"status":200,"version":"1.3.2"}]}', '{"result":{"status":"rolled_back","version":"1.3.2","checks":4,"exitCode":1},"rollouts":["1.4.0","1.3.2"],"outputs":{"deployed":"1.3.2","rolled_back":"true"},"checksAt":[0,5000,10000,15000],"elapsedMs":20000,"summary":true}', 5, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_172'), 'A flapping container never reaches three good answers in a row', '{"release":"1.4.0","previous":"1.3.2","policy":{"intervalMs":5000,"timeoutMs":60000,"okInARow":3},"health":[{"status":200,"version":"1.4.0"},"refused",{"status":200,"version":"1.4.0"},"refused",{"status":200,"version":"1.4.0"},"refused",{"status":200,"version":"1.4.0"},"refused",{"status":200,"version":"1.4.0"},"refused",{"status":200,"version":"1.4.0"},"refused"]}', '{"result":{"status":"rolled_back","version":"1.3.2","checks":12,"exitCode":1},"rollouts":["1.4.0","1.3.2"],"outputs":{"deployed":"1.3.2","rolled_back":"true"},"checksAt":[0,5000,10000,15000,20000,25000,30000,35000,40000,45000,50000,55000],"elapsedMs":60000,"summary":true}', 5, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_172'), 'First deploy without a previous version fails and rolls nothing back', '{"release":"1.4.0","previous":null,"policy":{"intervalMs":5000,"timeoutMs":20000,"okInARow":3},"health":["refused"]}', '{"result":{"status":"failed","version":"1.4.0","checks":4,"exitCode":1},"rollouts":["1.4.0"],"outputs":{"rolled_back":"false"},"checksAt":[0,5000,10000,15000],"elapsedMs":20000,"summary":true}', 5, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_172'), 'Stops as soon as the streak is complete, without sleeping again', '{"release":"1.4.0","previous":"1.3.2","policy":{"intervalMs":10000,"timeoutMs":25000,"okInARow":2},"health":[{"status":200,"version":"1.4.0"}]}', '{"result":{"status":"deployed","version":"1.4.0","checks":2,"exitCode":0},"rollouts":["1.4.0"],"outputs":{"deployed":"1.4.0","rolled_back":"false"},"checksAt":[0,10000],"elapsedMs":10000,"summary":true}', 5, false, true, 6);
