-- challenge chal_coding_gha_182 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_gha_182', (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'github-actions-ci-cd') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-gha-3-2' AND is_deleted = false LIMIT 1), 'reusable-node-ci', 'Write the shared Node CI workflow', 'Rice Rocket''s three repositories (app, admin, courier-app) each copied the same CI file, and the copies drifted: one still installs Node 20, one lost its npm cache, one has no time limit. The fix is one reusable workflow in the `rice-rocket/.github` repository that every repository calls with `uses: rice-rocket/.github/.github/workflows/node-ci.yml@v1`. The editor holds `node-ci.yml` with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that: callers must pass `working-directory` (a string), may pass `node-version` (a string, `24` when omitted) and `run-integration` (a boolean, off when omitted); every command runs in the caller''s folder with the caller''s Node version and an npm cache keyed on that folder''s lockfile; the integration tests run only when the caller sets `run-integration: true`; and the caller can read the line coverage as the workflow output `coverage`, taken from the `cov` step. Run grades the file by calling it the way the three repositories do, with a simulator of GitHub''s `workflow_call` inputs, secrets, expressions and outputs.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
