INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_182'), 1, 'Follow one value from the caller to its use: `with: { working-directory: api }` must be declared under `on.workflow_call.inputs`, then read where the commands run and where the cache looks for the lockfile. Do the same for `coverage` in the other direction: step, job, workflow.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_182'), 2, 'Look at `inputs.<name>` (not `github.event.inputs`, which belongs to `workflow_dispatch`), at the `type:` and `default:` of each input, at `jobs.<id>.outputs` versus `on.workflow_call.outputs.<name>.value`, and at which contexts each of those may use. Compare how a boolean and the string `''true''` behave in `==`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_182'), 3, 'A reusable deploy workflow with a typed input and an output: `on: { workflow_call: { inputs: { dry-run: { type: boolean, default: true } }, outputs: { url: { value: "${{ jobs.deploy.outputs.url }}" } } } }`, the job `deploy` with `outputs: { url: "${{ steps.release.outputs.url }}" }`, and a step guarded by `if: ${{ !inputs.dry-run }}`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_gha_182'), 'browser', 2000, 128, NULL, 'all_or_nothing', '[{"id":"call-inputs","label":"Inputs: the folder, the Node version, integration tests","code":"inputs:\n  working-directory:\n    type: string\n    required: true\n  node-version:\n    type: string\n    default: \"24\"\n  run-integration:\n    type: boolean\n    default: false"},{"id":"call-outputs","label":"Outputs: the test coverage, for the caller","code":"outputs:\n  coverage:\n    description: Line coverage of the tests, in percent\n    value: ${{ jobs.test.outputs.coverage }}"},{"id":"job-outputs","label":"test: expose the coverage step''s result","code":"outputs:\n  coverage: ${{ steps.cov.outputs.pct }}"},{"id":"run-folder","label":"test: run commands in the caller''s folder","code":"defaults:\n  run:\n    working-directory: ${{ inputs.working-directory }}"},{"id":"setup-node-inputs","label":"test: the caller''s Node version, with the npm cache","code":"- uses: actions/setup-node@v5\n  with:\n    node-version: ${{ inputs.node-version }}\n    cache: npm\n    cache-dependency-path: ${{ inputs.working-directory }}/package-lock.json"},{"id":"integration-if","label":"test: integration tests only when the caller asks","code":"- name: Integration tests\n  if: inputs.run-integration\n  run: npm run test:integration"},{"id":"call-outputs-steps","label":"Outputs: the test coverage, for the caller","code":"outputs:\n  coverage:\n    description: Line coverage of the tests, in percent\n    value: ${{ steps.cov.outputs.pct }}","distractor":true},{"id":"integration-if-string","label":"test: integration tests only when the caller asks","code":"- name: Integration tests\n  if: inputs.run-integration == ''true''\n  run: npm run test:integration","distractor":true},{"id":"setup-node-event-inputs","label":"test: the caller''s Node version, with the npm cache","code":"- uses: actions/setup-node@v5\n  with:\n    node-version: ${{ github.event.inputs.node-version }}\n    cache: npm\n    cache-dependency-path: ${{ github.event.inputs.working-directory }}/package-lock.json","distractor":true}]'::jsonb)
